use uuid::Uuid;

pub fn record_disbursement(loan_id: Uuid, user_id: Uuid, amount_cents: i64) {
    // BUG #1: format-string log instead of structured fields. Backends cannot index `loan_id` or `user_id`.
    tracing::info!("loan {} disbursed for user {} amount={}", loan_id, user_id, amount_cents);

    // BUG #2: unbounded metric label cardinality. Every distinct user_id creates a new time series
    // — high-cardinality explosion in Prometheus.
    metrics::counter!(
        "loan_disbursements_total",
        "user_id" => user_id.to_string(),
        "loan_id" => loan_id.to_string()
    ).increment(1);
}
